import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"Developer Manual","description":"","frontmatter":{},"headers":[],"relativePath":"dev-guide/index.md","filePath":"dev-guide/index.md","lastUpdated":1785993908000}'),s={name:"dev-guide/index.md"};function n(o,e,l,d,c,g){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="developer-manual" tabindex="-1">Developer Manual <a class="header-anchor" href="#developer-manual" aria-label="Permalink to &quot;Developer Manual&quot;">​</a></h1><p>Lertaro ships an open plugin SDK (<code>Lertaro.PluginSdk</code>) that third-party assemblies can target to extend search behavior, add context-menu actions, integrate with other windows, and customize the UI. This manual documents that surface.</p><ul><li><strong><a href="./architecture.html">Architecture</a></strong> — how the App, background Service, and plugins fit together.</li><li><strong><a href="./getting-started.html">Getting Started</a></strong> — scaffolding a plugin project and loading it.</li><li><strong>Plugin SDK Reference</strong>: <ul><li><strong><a href="./sdk/core-search-actions.html">Core Search &amp; Actions</a></strong> — contributing search results and result actions.</li><li><strong><a href="./sdk/system-adapters.html">System &amp; Dialog Adapters</a></strong> — integrating with File Explorer, native file dialogs, and other foreground windows.</li><li><strong><a href="./sdk/ui-extensions.html">UI &amp; Preview Extensions</a></strong> — sidebar filters, result columns, file previews, thumbnails, themes, and translations.</li><li><strong><a href="./sdk/abstractions.html">Shared Abstractions</a></strong> — the read-only models plugins receive (<code>ISearchResult</code>, <code>IPluginSearchWindow</code>) and configuration schema (<code>IConfigurable</code>).</li><li><strong><a href="./sdk/services.html">Host Services</a></strong> — static services the host exposes back to plugins (icons, favorites, history, file metadata, directory indexing, per-plugin settings, logging).</li></ul></li><li><strong><a href="./examples.html">Example Plugins</a></strong> — two real, shipped plugins as case studies.</li><li><strong><a href="./packaging.html">Packaging &amp; Deployment</a></strong> — how a built plugin DLL gets discovered and loaded.</li></ul><p>All interface signatures here were verified directly against the current <code>PluginSdk</code> source — if you find a discrepancy, the code is authoritative.</p>',4)])])}const p=t(s,[["render",n]]);export{u as __pageData,p as default};
